const __aivicBundle_5_analyzeSegmentUtilizationPatterns = (() => {
  function analyzeSegmentUtilizationPatterns(data: {
    usageLogsCount: number;
    usageLogs: Array<{
      logId: string;
      userId: string;
      featureName: string;
      usageTimestamp: string;
      actionType: string;
    }>;
    segmentationData: Array<{
      segmentId?: string;
      userId?: string;
      classificationDatetime?: string;
      segmentName: string;
    }>;
    analysisStartDate: string;
    analysisEndDate: string;
  }): {
    analysisStatus: string;
    segmentPatterns: Array<{
      segmentName: string;
      userCount: number;
      totalLogsInSegment: number;
      featureUsageFrequency: Array<{
        featureName: string;
        usageCount: number;
        frequencyRank: string;
      }>;
    }>;
    abandonmentPoints: Array<any>;
    errorMessage?: string;
  } {
    // Validate usage logs count
    if (data.usageLogsCount === 0 || data.usageLogs.length === 0) {
      throw new Error('利用ログ不足');
    }
  
    // Validate segmentation data is not empty
    if (!data.segmentationData || data.segmentationData.length === 0) {
      throw new Error('セグメント分類データが不足しています');
    }
  
    // Validate required fields in segmentation data
    const missingFieldsSet = new Set<string>();
    for (const segment of data.segmentationData) {
      if (segment.segmentId === undefined || segment.segmentId === null) {
        missingFieldsSet.add('segmentId');
      }
      if (segment.userId === undefined || segment.userId === null) {
        missingFieldsSet.add('userId');
      }
      if (segment.classificationDatetime === undefined || segment.classificationDatetime === null) {
        missingFieldsSet.add('classificationDatetime');
      }
    }
  
    if (missingFieldsSet.size > 0) {
      const missingFieldsArray = Array.from(missingFieldsSet);
      if (missingFieldsArray.length > 1) {
        throw new Error(`必須フィールドが欠落しています: ${missingFieldsArray.join(', ')}`);
      } else {
        throw new Error(`${missingFieldsArray[0]}が欠落しています`);
      }
    }
  
    // Parse date boundaries
    const startDate = new Date(data.analysisStartDate);
    const endDate = new Date(data.analysisEndDate);
  
    // Validate that at least one segmentation record is within analysis period
    const hasValidSegmentInRange = data.segmentationData.some((segment) => {
      const classDate = new Date(segment.classificationDatetime!);
      return classDate >= startDate && classDate <= endDate;
    });
  
    if (!hasValidSegmentInRange) {
      throw new Error('分析期間外のデータです');
    }
  
    // Build segment map: segmentName -> { userIds, logs }
    const segmentMap = new Map<
      string,
      {
        userIds: Set<string>;
        logs: Array<{
          logId: string;
          userId: string;
          featureName: string;
          usageTimestamp: string;
          actionType: string;
        }>;
      }
    >();
  
    // Initialize segments from segmentation data
    for (const segment of data.segmentationData) {
      const classDate = new Date(segment.classificationDatetime!);
      if (classDate >= startDate && classDate <= endDate) {
        if (!segmentMap.has(segment.segmentName)) {
          segmentMap.set(segment.segmentName, {
            userIds: new Set(),
            logs: [],
          });
        }
        segmentMap.get(segment.segmentName)!.userIds.add(segment.userId!);
      }
    }
  
    // Assign logs to segments based on userId
    for (const log of data.usageLogs) {
      const logDate = new Date(log.usageTimestamp);
      if (logDate >= startDate && logDate <= endDate) {
        for (const [, segmentData] of segmentMap.entries()) {
          if (segmentData.userIds.has(log.userId)) {
            segmentData.logs.push(log);
          }
        }
      }
    }
  
    // Build segment patterns
    const segmentPatterns: Array<{
      segmentName: string;
      userCount: number;
      totalLogsInSegment: number;
      featureUsageFrequency: Array<{
        featureName: string;
        usageCount: number;
        frequencyRank: string;
      }>;
    }> = [];
  
    for (const [segmentName, segmentData] of segmentMap.entries()) {
      const featureMap = new Map<string, number>();
  
      for (const log of segmentData.logs) {
        const count = featureMap.get(log.featureName) || 0;
        featureMap.set(log.featureName, count + 1);
      }
  
      // Sort features by usage count (descending) and assign frequency ranks
      const sortedFeatures = Array.from(featureMap.entries())
        .sort((a, b) => b[1] - a[1])
        .map(([featureName, usageCount], index, array) => {
          let frequencyRank: string;
          if (array.length === 1) {
            frequencyRank = 'high';
          } else if (index === 0) {
            frequencyRank = 'high';
          } else if (index === array.length - 1) {
            frequencyRank = 'low';
          } else {
            frequencyRank = 'medium';
          }
          return {
            featureName,
            usageCount,
            frequencyRank,
          };
        });
  
      segmentPatterns.push({
        segmentName,
        userCount: segmentData.userIds.size,
        totalLogsInSegment: segmentData.logs.length,
        featureUsageFrequency: sortedFeatures,
      });
    }
  
    // Build abandonment points (empty array as per business logic)
    const abandonmentPoints: Array<any> = [];
  
    return {
      analysisStatus: 'success',
      segmentPatterns,
      abandonmentPoints,
    };
  }
  return { analyzeSegmentUtilizationPatterns };
})();
export const analyzeSegmentUtilizationPatterns = __aivicBundle_5_analyzeSegmentUtilizationPatterns.analyzeSegmentUtilizationPatterns;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeSegmentUtilizationPatterns */

/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMenuGenerationSuccessRateImprovement exports=analyzeMenuGenerationSuccessRateImprovement */
const __aivicBundle_6_analyzeMenuGenerationSuccessRateImprovement = (() => {
  function analyzeMenuGenerationSuccessRateImprovement(input: any): any {
    const pre = input.preImprovementSuccessRate ?? input.baselineSuccessRate;
    const post = input.postImprovementSuccessRate ?? input.improvedSuccessRate;
    const minimum = input.minimumThreshold;
    const target = input.improvementTargetRate;
  
    let currentSuccessRate = post;
    if (input.successfulMenusAfter !== undefined && input.totalMenusGenerated !== undefined) {
      currentSuccessRate = Math.round((input.successfulMenusAfter / input.totalMenusGenerated) * 100);
    }
  
    const successRateImprovement = post - pre;
  
    const meetsMinimumThreshold = currentSuccessRate >= minimum;
  
    let progressRate = 0;
    if (target !== undefined) {
      const totalTargetImprovement = target - pre;
      if (totalTargetImprovement > 0) {
        progressRate = (successRateImprovement / totalTargetImprovement) * 100;
      }
    }
  
    let priorityScore = 0;
    if (meetsMinimumThreshold) {
      priorityScore = Math.min(100, Math.round(progressRate + 15));
    } else {
      priorityScore = Math.round(progressRate * 0.5);
    }
  
    let priorityDecision = "LOW";
    if (meetsMinimumThreshold && progressRate > 50) {
      priorityDecision = "HIGH";
    } else if (meetsMinimumThreshold && progressRate > 25) {
      priorityDecision = "MEDIUM";
    }
  
    if (input.successfulMenusAfter !== undefined && input.totalMenusGenerated !== undefined) {
      const rateGap = currentSuccessRate - minimum;
      const isImprovementSufficient = currentSuccessRate >= minimum;
  
      return {
        isImprovementSufficient,
        currentSuccessRate,
        minimumRequiredRate: minimum,
        rateGap,
        improvementMessage: isImprovementSufficient
          ? `改善が十分です。現在の成功率: ${currentSuccessRate}%`
          : `改善が不十分です。現在の成功率: ${currentSuccessRate}%、必要な成功率: ${minimum}%`,
        nextActionRecommended: isImprovementSufficient ? "maintain_current_level" : "next_improvement_cycle",
        shouldPresentNextCycleOption: !isImprovementSufficient,
        warningLevel: isImprovementSufficient ? "info" : "warning",
        priorityReviewRequired: !isImprovementSufficient,
        priorityDecision,
        justificationDetails: {
          successRateImprovement,
          progressRate,
          meetsMinimumThreshold,
          priorityScore,
        },
      };
    }
  
    return {
      priorityDecision,
      justificationDetails: {
        successRateImprovement,
        progressRate,
        meetsMinimumThreshold,
        priorityScore,
      },
    };
  }
  return { analyzeMenuGenerationSuccessRateImprovement };
})();
