/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMenuGenerationSuccessRateComparison exports=analyzeMenuGenerationSuccessRateComparison */
const __aivicBundle_7_analyzeMenuGenerationSuccessRateComparison = (() => {
  function analyzeMenuGenerationSuccessRateComparison(
    beforeData: {
      success_count?: number;
      total_attempts?: number;
      period_start?: string;
      period_end?: string;
    },
    afterData: {
      success_count?: number;
      total_attempts?: number;
      period_start?: string;
      period_end?: string;
    }
  ): {
    before_success_rate: number;
    after_success_rate: number;
    improvement_percentage: number;
    status: string;
    error_message: string | null;
  } {
    // Validate beforeData.success_count
    if (beforeData.success_count === undefined || beforeData.success_count === null) {
      throw new Error('改善前データの成功数が欠落しています');
    }
  
    // Validate beforeData.total_attempts
    if (beforeData.total_attempts === undefined || beforeData.total_attempts === null) {
      throw new Error('改善前データの試行数が欠落しています');
    }
  
    // Validate beforeData period
    if (beforeData.period_start === undefined || beforeData.period_start === null) {
      throw new Error('改善前データの期間情報が欠落しています');
    }
    if (beforeData.period_end === undefined || beforeData.period_end === null) {
      throw new Error('改善前データの期間情報が欠落しています');
    }
  
    // Validate afterData.success_count
    if (afterData.success_count === undefined || afterData.success_count === null) {
      throw new Error('改善後データの成功数が欠落しています');
    }
  
    // Validate afterData.total_attempts
    if (afterData.total_attempts === undefined || afterData.total_attempts === null) {
      throw new Error('改善後データの試行数が欠落しています');
    }
  
    // Validate afterData period
    if (afterData.period_start === undefined || afterData.period_start === null) {
      throw new Error('改善後データの期間情報が欠落しています');
    }
    if (afterData.period_end === undefined || afterData.period_end === null) {
      throw new Error('改善後データの期間情報が欠落しています');
    }
  
    // Validate beforeData constraints
    if (beforeData.success_count < 0) {
      throw new Error('改善前データの成功数は非負である必要があります');
    }
    if (beforeData.success_count > beforeData.total_attempts) {
      throw new Error('改善前データの成功数は総試行数を超えることはできません');
    }
  
    // Validate afterData constraints
    if (afterData.success_count < 0) {
      throw new Error('改善後データの成功数は非負である必要があります');
    }
    if (afterData.success_count > afterData.total_attempts) {
      throw new Error('改善後データの成功数は総試行数を超えることはできません');
    }
  
    // Calculate success rates
    const beforeSuccessRate = beforeData.success_count / beforeData.total_attempts;
    const afterSuccessRate = afterData.success_count / afterData.total_attempts;
  
    // Calculate improvement percentage
    const improvementPercentage =
      beforeSuccessRate > 0
        ? ((afterSuccessRate - beforeSuccessRate) / beforeSuccessRate) * 100
        : 0;
  
    return {
      before_success_rate: beforeSuccessRate,
      after_success_rate: afterSuccessRate,
      improvement_percentage: improvementPercentage,
      status: 'completed',
      error_message: null,
    };
  }
  return { analyzeMenuGenerationSuccessRateComparison };
})();
export const analyzeMenuGenerationSuccessRateComparison = __aivicBundle_7_analyzeMenuGenerationSuccessRateComparison.analyzeMenuGenerationSuccessRateComparison;
