const __aivicBundle_10_determineImprovementPriority = (() => {
  function determineImprovementPriority(input: {
    improvement_rate: number;
  }): {
    progress_status: string;
    has_improvement_effect: boolean;
    priority_level: string;
  } {
    const { improvement_rate } = input;
  
    if (improvement_rate === 0) {
      return {
        progress_status: 'no_progress',
        has_improvement_effect: false,
        priority_level: 'low',
      };
    }
  
    if (improvement_rate > 0) {
      return {
        progress_status: 'progress',
        has_improvement_effect: true,
        priority_level: 'high',
      };
    }
  
    return {
      progress_status: 'no_progress',
      has_improvement_effect: false,
      priority_level: 'low',
    };
  }
  return { determineImprovementPriority };
})();
