/* AIVIC_FUNCTION_BUNDLE_START owner=validateAppUsageLogsDataQuality exports=validateAppUsageLogsDataQuality */
const __aivicBundle_11_validateAppUsageLogsDataQuality = (() => {
  function validateAppUsageLogsDataQuality(
    appUsageLogs: Array<{
      log_id: string;
      user_id: string | null;
      feature_name: string;
      session_duration_seconds: number | null;
      timestamp: string;
      action_type: string | undefined;
      screen_name: string;
    }>
  ): DataQualityValidationResult {
    const missing_value_errors: Array<{
      log_row_number: number;
      column_name: string;
      error_type: string;
      detected_value: any;
      severity: string;
    }> = [];
  
    const anomalous_value_errors: Array<{
      log_row_number: number;
      column_name: string;
      error_type: string;
      detected_value: any;
      validation_rule: string;
      severity: string;
    }> = [];
  
    const validation_log: Array<{ message: string }> = [];
  
    let total_normal_records = 0;
  
    appUsageLogs.forEach((log, index) => {
      const row_number = index + 1;
      let has_error = false;
  
      // Check user_id for missing value
      if (log.user_id === null || log.user_id === undefined) {
        missing_value_errors.push({
          log_row_number: row_number,
          column_name: "user_id",
          error_type: "missing_value",
          detected_value: log.user_id,
          severity: "error",
        });
        validation_log.push({
          message: `Row ${row_number}: missing_value detected in user_id`,
        });
        has_error = true;
      }
  
      // Check feature_name for missing value
      if (
        log.feature_name === null ||
        log.feature_name === undefined ||
        log.feature_name === ""
      ) {
        missing_value_errors.push({
          log_row_number: row_number,
          column_name: "feature_name",
          error_type: "missing_value",
          detected_value: log.feature_name,
          severity: "error",
        });
        validation_log.push({
          message: `Row ${row_number}: missing_value detected in feature_name`,
        });
        has_error = true;
      }
  
      // Check session_duration_seconds for missing value
      if (log.session_duration_seconds === null) {
        missing_value_errors.push({
          log_row_number: row_number,
          column_name: "session_duration_seconds",
          error_type: "missing_value",
          detected_value: log.session_duration_seconds,
          severity: "error",
        });
        validation_log.push({
          message: `Row ${row_number}: missing_value detected in session_duration_seconds`,
        });
        has_error = true;
      }
  
      // Check action_type for missing value
      if (log.action_type === undefined || log.action_type === null) {
        missing_value_errors.push({
          log_row_number: row_number,
          column_name: "action_type",
          error_type: "missing_value",
          detected_value: log.action_type,
          severity: "error",
        });
        validation_log.push({
          message: `Row ${row_number}: missing_value detected in action_type`,
        });
        has_error = true;
      }
  
      // Check session_duration_seconds for anomalous value (negative)
      if (
        log.session_duration_seconds !== null &&
        log.session_duration_seconds < 0
      ) {
        anomalous_value_errors.push({
          log_row_number: row_number,
          column_name: "session_duration_seconds",
          error_type: "anomalous_value",
          detected_value: log.session_duration_seconds,
          validation_rule: "session_duration_seconds >= 0",
          severity: "error",
        });
        validation_log.push({
          message: `Row ${row_number}: anomalous_value detected in session_duration_seconds (negative value)`,
        });
        has_error = true;
      }
  
      // Check session_duration_seconds for anomalous value (unrealistic)
      if (
        log.session_duration_seconds !== null &&
        log.session_duration_seconds > 86400
      ) {
        anomalous_value_errors.push({
          log_row_number: row_number,
          column_name: "session_duration_seconds",
          error_type: "anomalous_value",
          detected_value: log.session_duration_seconds,
          validation_rule: "session_duration_seconds <= 86400",
          severity: "warning",
        });
        validation_log.push({
          message: `Row ${row_number}: anomalous_value detected in session_duration_seconds (unrealistic duration)`,
        });
        has_error = true;
      }
  
      // Check timestamp for invalid date format
      if (log.timestamp) {
        const dateTest = new Date(log.timestamp);
        if (isNaN(dateTest.getTime())) {
          anomalous_value_errors.push({
            log_row_number: row_number,
            column_name: "timestamp",
            error_type: "anomalous_value",
            detected_value: log.timestamp,
            validation_rule: "timestamp must be valid ISO 8601 format",
            severity: "error",
          });
          validation_log.push({
            message: `Row ${row_number}: anomalous_value detected in timestamp (invalid format)`,
          });
          has_error = true;
        }
      }
  
      if (!has_error) {
        total_normal_records++;
      }
    });
  
    const total_records_validated = appUsageLogs.length;
    const total_errors_detected =
      missing_value_errors.length + anomalous_value_errors.length;
  
    const quality_score =
      total_records_validated > 0
        ? Math.round(
            ((total_normal_records / total_records_validated) * 100) * 100
          ) / 100
        : 100;
  
    const error_count =
      missing_value_errors.filter((e) => e.severity === "error").length +
      anomalous_value_errors.filter((e) => e.severity === "error").length;
    const warning_count = anomalous_value_errors.filter(
      (e) => e.severity === "warning"
    ).length;
  
    return {
      missing_value_errors,
      anomalous_value_errors,
      validation_log,
      total_records_validated,
      total_errors_detected,
      total_normal_records,
      quality_score,
      validation_timestamp: new Date().toISOString(),
      report_summary: {
        total_missing_values_detected: missing_value_errors.length,
        total_anomalous_values_detected: anomalous_value_errors.length,
        error_severity_distribution: {
          error: error_count,
          warning: warning_count,
        },
        processing_status: "completed",
      },
    };
  }
  return { validateAppUsageLogsDataQuality };
})();
export const validateAppUsageLogsDataQuality = __aivicBundle_11_validateAppUsageLogsDataQuality.validateAppUsageLogsDataQuality;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateAppUsageLogsDataQuality */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateDataQuality exports=validateDataQuality */
const __aivicBundle_12_validateDataQuality = (() => {
  function validateDataQuality(
    input: any,
    options?: { enable_anomaly_detection?: boolean; enable_traceability?: boolean }
  ): any {
    const enableAnomalyDetection = options?.enable_anomaly_detection ?? false;
    const enableTraceability = options?.enable_traceability ?? false;
  
    // Normalize input: handle both object with records field and direct array
    let records: Array<any> = [];
    let validationRules: any = null;
  
    if (Array.isArray(input)) {
      records = input;
      validationRules = {
        allow_null_fields: [],
        numeric_field_ranges: {},
        required_fields: [],
      };
    } else if (input && typeof input === "object" && "records" in input) {
      records = Array.isArray(input.records) ? input.records : [];
      validationRules = input.validation_rules || {
        allow_null_fields: [],
        numeric_field_ranges: {},
        required_fields: [],
      };
    }
  
    const totalRecordsProcessed = records.length;
    const validRecords: Array<any> = [];
    const excludedRecords: Array<{
      record_id: string;
      exclusion_reason: string;
      excluded_at: string;
    }> = [];
    const detectedAnomalies: Array<any> = [];
    const correctionLogs: Array<any> = [];
  
    const now = new Date().toISOString();
    const allowNullFields = validationRules?.allow_null_fields || [];
    const numericRanges = validationRules?.numeric_field_ranges || {};
    const requiredFields = validationRules?.required_fields || [];
  
    // Process each record
    for (const record of records) {
      let hasError = false;
      let errorReason = "";
      let anomalyInfo: any = null;
  
      // Check for missing required fields
      for (const field of requiredFields) {
        const value = record[field];
        if (
          value === null ||
          value === undefined ||
          (typeof value === "string" && value.trim() === "")
        ) {
          if (!allowNullFields.includes(field)) {
            hasError = true;
            errorReason = "欠損値";
            break;
          }
        }
      }
  
      // Check for anomalous numeric values
      if (!hasError) {
        for (const [fieldName, range] of Object.entries(numericRanges)) {
          const value = record[fieldName];
          if (value !== null && value !== undefined) {
            const numValue = Number(value);
            if (
              !isNaN(numValue) &&
              (numValue < (range as any).min || numValue > (range as any).max)
            ) {
              hasError = true;
              errorReason = "異常値";
  
              const anomalyType =
                numValue < (range as any).min ? "outlier_low" : "outlier_high";
              anomalyInfo = {
                user_id: record.user_id || record.userId || "",
                field: fieldName,
                original_value: numValue,
                anomaly_type: anomalyType,
              };
  
              if (enableAnomalyDetection) {
                detectedAnomalies.push(anomalyInfo);
              }
  
              if (enableTraceability) {
                const correctedValue =
                  numValue < (range as any).min
                    ? (range as any).min
                    : (range as any).max;
                correctionLogs.push({
                  user_id: record.user_id || record.userId || "",
                  field: fieldName,
                  original_value: numValue,
                  corrected_value: correctedValue,
                  rule_applied: `clamp_to_range[${(range as any).min},${(range as any).max}]`,
                  timestamp: now,
                });
              }
  
              break;
            }
          }
        }
      }
  
      // Classify record
      if (hasError) {
        const recordId = record.record_id || record.id || "";
        excludedRecords.push({
          record_id: recordId,
          exclusion_reason: errorReason,
          excluded_at: now,
        });
      } else {
        validRecords.push(record);
      }
    }
  
    const validRecordsCount = validRecords.length;
    const excludedRecordsCount = excludedRecords.length;
    const qualityScore =
      totalRecordsProcessed > 0
        ? Math.round((validRecordsCount / totalRecordsProcessed) * 10000) / 100
        : 100.0;
  
    const baseResult = {
      valid_records: validRecords,
      excluded_records: excludedRecords,
      total_records_processed: totalRecordsProcessed,
      valid_records_count: validRecordsCount,
      excluded_records_count: excludedRecordsCount,
      validation_passed: excludedRecordsCount === 0,
      quality_score: qualityScore,
    };
  
    // Add anomaly detection fields if enabled
    if (enableAnomalyDetection) {
      const result = {
        ...baseResult,
        validation_status: detectedAnomalies.length > 0 ? "detected" : "passed",
        anomaly_count: detectedAnomalies.length,
        detected_anomalies: detectedAnomalies,
      };
  
      // Add traceability fields if also enabled
      if (enableTraceability) {
        return {
          ...result,
          traceability_enabled: true,
          correction_timestamp: now,
          correction_logs: correctionLogs,
        };
      }
  
      return result;
    }
  
    // Add traceability fields if enabled (without anomaly detection)
    if (enableTraceability) {
      return {
        ...baseResult,
        traceability_enabled: true,
        correction_timestamp: now,
        correction_logs: correctionLogs,
      };
    }
  
    return baseResult;
  }
  return { validateDataQuality };
})();
export const validateDataQuality: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_12_validateDataQuality.validateDataQuality as (...args: any[]) => any)(...args);
