/* AIVIC_FUNCTION_BUNDLE_START owner=applyAnomalyCorrection exports=applyAnomalyCorrection */
const __aivicBundle_13_applyAnomalyCorrection = (() => {
  function applyAnomalyCorrection(
    data: Array<any>,
    config: {
      rules: Array<{
        field: string;
        rule_type: string;
        params: Record<string, any>;
      }>;
      fallback_strategy: string;
    }
  ): {
    data: Array<any>;
    correction_log: Array<{
      user_id?: string;
      field: string;
      original_value: any;
      corrected_value: any;
      rule_applied: string;
      timestamp?: string;
    }>;
    dataset_id?: string;
    traceability_enabled?: boolean;
    correction_timestamp?: string;
  } {
    const correctionLog: Array<{
      user_id?: string;
      field: string;
      original_value: any;
      corrected_value: any;
      rule_applied: string;
      timestamp?: string;
    }> = [];
  
    const correctedData = data.map((record) => {
      const correctedRecord = { ...record };
  
      for (const rule of config.rules) {
        const fieldValue = correctedRecord[rule.field];
  
        if (fieldValue === null || fieldValue === undefined) {
          continue;
        }
  
        let correctedValue: any = fieldValue;
        let shouldCorrect = false;
  
        if (rule.rule_type === "min_threshold") {
          const minimumValue = rule.params.minimum_value;
          if (typeof fieldValue === "number" && fieldValue < minimumValue) {
            correctedValue = minimumValue;
            shouldCorrect = true;
          }
        } else if (rule.rule_type === "max_threshold") {
          const maximumValue = rule.params.maximum_value;
          if (typeof fieldValue === "number" && fieldValue > maximumValue) {
            correctedValue = maximumValue;
            shouldCorrect = true;
          }
        } else if (rule.rule_type === "iqr_based_outlier") {
          const lowerPercentile = rule.params.lower_percentile;
          const upperPercentile = rule.params.upper_percentile;
  
          const fieldValues = data
            .map((r) => r[rule.field])
            .filter((v) => typeof v === "number")
            .sort((a, b) => a - b);
  
          if (fieldValues.length > 0) {
            const lowerIndex = Math.floor(
              (fieldValues.length - 1) * (lowerPercentile / 100)
            );
            const upperIndex = Math.floor(
              (fieldValues.length - 1) * (upperPercentile / 100)
            );
  
            const q1 = fieldValues[lowerIndex];
            const q3 = fieldValues[upperIndex];
            const iqr = q3 - q1;
  
            const lowerBound = q1 - 1.5 * iqr;
            const upperBound = q3 + 1.5 * iqr;
  
            if (
              typeof fieldValue === "number" &&
              (fieldValue < lowerBound || fieldValue > upperBound)
            ) {
              if (config.fallback_strategy === "mean_imputation") {
                const mean =
                  fieldValues.reduce((sum, v) => sum + v, 0) / fieldValues.length;
                correctedValue = Math.round(mean);
              }
              shouldCorrect = true;
            }
          }
        }
  
        if (shouldCorrect && correctedValue !== fieldValue) {
          correctedRecord[rule.field] = correctedValue;
          correctionLog.push({
            user_id: record.user_id,
            field: rule.field,
            original_value: fieldValue,
            corrected_value: correctedValue,
            rule_applied: rule.rule_type,
            timestamp: new Date().toISOString(),
          });
        }
      }
  
      return correctedRecord;
    });
  
    return {
      data: correctedData,
      correction_log: correctionLog,
      traceability_enabled: true,
      correction_timestamp: new Date().toISOString(),
    };
  }
  return { applyAnomalyCorrection };
})();
export const applyAnomalyCorrection = __aivicBundle_13_applyAnomalyCorrection.applyAnomalyCorrection;
/* AIVIC_FUNCTION_BUNDLE_END owner=applyAnomalyCorrection */

/* AIVIC_FUNCTION_BUNDLE_START owner=getAnalysisResult exports=getAnalysisResult */
const __aivicBundle_14_getAnalysisResult = (() => {
  function getAnalysisResult(
    correctedDataset: { data: Array<any>; dataset_id?: string; correction_log?: Array<any> },
    options: { group_by: string; metrics: string[] }
  ): {
    used_dataset_id: string;
    data_quality_status: string;
    analysis_groups: Array<{
      feature_name?: string;
      mean_usage_frequency?: number;
      mean_cooking_time?: number;
      record_count: number;
    }>;
  } {
    const datasetId = correctedDataset.dataset_id || "unknown";
    
    const dataQualityStatus =
      correctedDataset.correction_log && correctedDataset.correction_log.length > 0
        ? "corrected"
        : "raw";
  
    const groupByField = options.group_by;
    const requestedMetrics = options.metrics || [];
  
    const groupMap = new Map<
      string,
      {
        usageFrequencies: Array<number>;
        cookingTimes: Array<number>;
        count: number;
      }
    >();
  
    for (const record of correctedDataset.data) {
      const groupKey = String(record[groupByField] || "unknown");
  
      if (!groupMap.has(groupKey)) {
        groupMap.set(groupKey, {
          usageFrequencies: [],
          cookingTimes: [],
          count: 0,
        });
      }
  
      const group = groupMap.get(groupKey)!;
      group.count += 1;
  
      if (
        record.usage_frequency !== undefined &&
        record.usage_frequency !== null
      ) {
        group.usageFrequencies.push(record.usage_frequency);
      }
  
      if (
        record.cooking_time_minutes !== undefined &&
        record.cooking_time_minutes !== null
      ) {
        group.cookingTimes.push(record.cooking_time_minutes);
      }
    }
  
    const analysisGroups: Array<{
      feature_name?: string;
      mean_usage_frequency?: number;
      mean_cooking_time?: number;
      record_count: number;
    }> = [];
  
    for (const [groupKey, groupData] of groupMap.entries()) {
      const groupResult: {
        feature_name?: string;
        mean_usage_frequency?: number;
        mean_cooking_time?: number;
        record_count: number;
      } = {
        record_count: groupData.count,
      };
  
      if (groupByField === "feature_name") {
        groupResult.feature_name = groupKey;
      }
  
      if (requestedMetrics.includes("mean_usage_frequency")) {
        if (groupData.usageFrequencies.length > 0) {
          const sum = groupData.usageFrequencies.reduce((a, b) => a + b, 0);
          groupResult.mean_usage_frequency = sum / groupData.usageFrequencies.length;
        }
      }
  
      if (requestedMetrics.includes("mean_cooking_time")) {
        if (groupData.cookingTimes.length > 0) {
          const sum = groupData.cookingTimes.reduce((a, b) => a + b, 0);
          groupResult.mean_cooking_time = sum / groupData.cookingTimes.length;
        }
      }
  
      analysisGroups.push(groupResult);
    }
  
    return {
      used_dataset_id: datasetId,
      data_quality_status: dataQualityStatus,
      analysis_groups: analysisGroups,
    };
  }
  return { getAnalysisResult };
})();
export const getAnalysisResult = __aivicBundle_14_getAnalysisResult.getAnalysisResult;
/* AIVIC_FUNCTION_BUNDLE_END owner=getAnalysisResult */

/* AIVIC_FUNCTION_BUNDLE_START owner=determineMarketAnalysisExecution exports=determineMarketAnalysisExecution */
const __aivicBundle_15_determineMarketAnalysisExecution = (() => {
  function determineMarketAnalysisExecution(input: {
    currentDate: Date;
    lastExecutionDate: Date;
    lastAnalysisDate?: Date;
    targetQuarterStart?: Date;
  }): {
    shouldExecute: boolean;
    analysisTypes: string[];
    executionStatus: string;
    lastExecutedAt: Date;
    quarterCode?: string;
    nextScheduledDate?: Date;
    reason?: string;
  } {
    const { currentDate, lastExecutionDate } = input;
  
    const month = currentDate.getUTCMonth();
    const date = currentDate.getUTCDate();
    const year = currentDate.getUTCFullYear();
  
    const isQuarterStart =
      (month === 0 && date === 1) ||
      (month === 3 && date === 1) ||
      (month === 6 && date === 1) ||
      (month === 9 && date === 1);
  
    const quarterCode = isQuarterStart
      ? `Q${Math.floor(month / 3) + 1}_${year}`
      : undefined;
  
    const lastExecMonth = lastExecutionDate.getUTCMonth();
    const lastExecYear = lastExecutionDate.getUTCFullYear();
    const lastExecQuarter = Math.floor(lastExecMonth / 3);
  
    const currentQuarter = Math.floor(month / 3);
  
    const daysDifference = Math.floor(
      (currentDate.getTime() - lastExecutionDate.getTime()) / (1000 * 60 * 60 * 24)
    );
  
    let shouldExecute = false;
    let executionStatus = 'waiting';
  
    if (!isQuarterStart) {
      shouldExecute = false;
      executionStatus = 'waiting';
    } else if (
      lastExecYear === year &&
      lastExecQuarter === currentQuarter
    ) {
      shouldExecute = false;
      executionStatus = 'already_executed';
    } else if (daysDifference >= 90) {
      shouldExecute = true;
      executionStatus = 'ready';
    } else {
      shouldExecute = false;
      executionStatus = 'waiting';
    }
  
    const analysisTypes = shouldExecute
      ? [
          'user_pain_analysis',
          'differentiation_axis_verification',
          'competitor_analysis',
        ]
      : [];
  
    return {
      shouldExecute,
      analysisTypes,
      executionStatus,
      lastExecutedAt: lastExecutionDate,
      quarterCode,
    };
  }
  return { determineMarketAnalysisExecution };
})();
export const determineMarketAnalysisExecution = __aivicBundle_15_determineMarketAnalysisExecution.determineMarketAnalysisExecution;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineMarketAnalysisExecution */

