/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeQualitativeQuantitativeDataIntegration exports=analyzeQualitativeQuantitativeDataIntegration */
const __aivicBundle_20_analyzeQualitativeQuantitativeDataIntegration = (() => {
  function analyzeQualitativeQuantitativeDataIntegration(input: {
    qualitativeData?: {
      interviewId: string;
      userId: string;
      segmentType: string;
      painCategory: string;
      feedbackText: string;
      recordedAt: string;
    };
    quantitativeData: {
      featureId?: string;
      usageFrequency: number | string | boolean | null | undefined;
      abandonmentRate: number | null | undefined;
      improvementPriority: number;
      sampleSize: number | boolean;
    };
  }): {
    status: number;
    painPriorityMatrix: {
      items: Array<{
        painFactor: string;
        frequency: number;
        impact: number;
        priorityScore: number;
      }>;
    };
  } {
    const { qualitativeData, quantitativeData } = input;
  
    if (!quantitativeData) {
      throw new Error('データ形式エラー: quantitativeData が必須です');
    }
  
    const requiredNumericFields = [
      'usageFrequency',
      'abandonmentRate',
      'improvementPriority',
      'sampleSize',
    ] as const;
  
    for (const field of requiredNumericFields) {
      const value = quantitativeData[field];
  
      if (value === null) {
        throw new Error(`データ形式エラー: ${field} が null です`);
      }
  
      if (value === undefined) {
        throw new Error(`データ形式エラー: ${field} が undefined です`);
      }
  
      if (typeof value === 'string') {
        throw new Error(`データ形式エラー: ${field} が文字列形式です`);
      }
  
      if (typeof value === 'boolean') {
        throw new Error(`データ形式エラー: ${field} が boolean 形式です`);
      }
  
      if (typeof value !== 'number') {
        throw new Error(`データ形式エラー: ${field} が数値形式ではありません`);
      }
  
      if (isNaN(value)) {
        throw new Error(`データ形式エラー: ${field} が NaN です`);
      }
    }
  
    const painFactor = qualitativeData?.painCategory || 'unknown_pain';
    const frequency = Math.round(quantitativeData.usageFrequency as number);
    const impact = Math.round(
      (1 - (quantitativeData.abandonmentRate as number)) * 100
    );
    const priorityScore = Math.round(
      ((quantitativeData.improvementPriority as number) / 10) *
        (1 - (quantitativeData.abandonmentRate as number)) *
        100
    );
  
    return {
      status: 200,
      painPriorityMatrix: {
        items: [
          {
            painFactor,
            frequency,
            impact,
            priorityScore,
          },
        ],
      },
    };
  }
  return { analyzeQualitativeQuantitativeDataIntegration };
})();
export const analyzeQualitativeQuantitativeDataIntegration: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_20_analyzeQualitativeQuantitativeDataIntegration.analyzeQualitativeQuantitativeDataIntegration as (...args: any[]) => any)(...args);
