const __aivicBundle_32_extractSegmentedUsagePatterns = (() => {
  function extractSegmentedUsagePatterns(
    inputData: Array<{
      userId: string;
      segmentName: string;
      date: string;
      mealGenerationSuccessCount: number;
      cookingTimeMinutes: number;
      userSatisfactionScore: number;
    }>,
    startDate: string,
    endDate: string
  ): {
    totalRecordCount: number;
    records: Array<{
      userId: string;
      segmentName: string;
      date: string;
      mealGenerationSuccessCount: number;
      cookingTimeMinutes: number;
      userSatisfactionScore: number;
    }>;
    segments: Array<{
      segmentName: string;
      totalMealGenerationSuccessCount: number;
      averageCookingTimeMinutes: number;
      averageUserSatisfactionScore: number;
    }>;
  } {
    const filteredRecords = inputData.filter((record) => {
      return record.date >= startDate && record.date <= endDate;
    });
  
    const segmentMap = new Map<
      string,
      {
        totalMealGenerationSuccessCount: number;
        totalCookingTimeMinutes: number;
        totalUserSatisfactionScore: number;
        recordCount: number;
      }
    >();
  
    for (const record of filteredRecords) {
      const existing = segmentMap.get(record.segmentName) || {
        totalMealGenerationSuccessCount: 0,
        totalCookingTimeMinutes: 0,
        totalUserSatisfactionScore: 0,
        recordCount: 0,
      };
  
      existing.totalMealGenerationSuccessCount +=
        record.mealGenerationSuccessCount;
      existing.totalCookingTimeMinutes += record.cookingTimeMinutes;
      existing.totalUserSatisfactionScore += record.userSatisfactionScore;
      existing.recordCount += 1;
  
      segmentMap.set(record.segmentName, existing);
    }
  
    const segments = Array.from(segmentMap.entries()).map(
      ([segmentName, data]) => ({
        segmentName,
        totalMealGenerationSuccessCount: data.totalMealGenerationSuccessCount,
        averageCookingTimeMinutes:
          data.recordCount > 0
            ? data.totalCookingTimeMinutes / data.recordCount
            : 0,
        averageUserSatisfactionScore:
          data.recordCount > 0
            ? data.totalUserSatisfactionScore / data.recordCount
            : 0,
      })
    );
  
    return {
      totalRecordCount: filteredRecords.length,
      records: filteredRecords,
      segments,
    };
  }
  return { extractSegmentedUsagePatterns };
})();
