const __aivicBundle_34_detectAndExcludeAnomalies = (() => {
  function detectAndExcludeAnomalies(
    records: any[]
  ): {
    validData: any[];
    anomalies: any[];
    validDataCount: number;
    anomalyCount: number;
    processCompleted: boolean;
    hasError: boolean;
  } {
    const validData: any[] = [];
    const anomalies: any[] = [];
  
    for (const record of records) {
      const successRate = record.recipeGenerationSuccessRate;
  
      if (successRate > 100) {
        anomalies.push({
          ...record,
          reason: '成功率が100%を超過',
        });
      } else if (successRate < 0) {
        anomalies.push({
          ...record,
          reason: '成功率がマイナス',
        });
      } else {
        validData.push(record);
      }
    }
  
    return {
      validData,
      anomalies,
      validDataCount: validData.length,
      anomalyCount: anomalies.length,
      processCompleted: true,
      hasError: false,
    };
  }
  return { detectAndExcludeAnomalies };
})();
